// Same-origin multiplayer via BroadcastChannel (works across tabs) with graceful solo fallback.
export class Net {
  constructor() {
    this.id = 'p' + Math.random().toString(36).slice(2, 9);
    this.remotes = new Map();
    this.handlers = {};
    this.lastSend = 0;
    this.channel = null;
    try {
      this.channel = new BroadcastChannel('sunset-city-rp');
      this.channel.onmessage = (e) => this.onMessage(e.data);
    } catch { this.channel = null; }
    this.online = !!this.channel;
  }

  on(handlers) { this.handlers = { ...this.handlers, ...handlers }; }

  announce(me) {
    this.me = me;
    this.send({ t: 'join', id: this.id, player: me });
  }

  send(msg) {
    if (!this.channel) return;
    try { this.channel.postMessage(msg); } catch {}
  }

  onMessage(msg) {
    if (!msg || msg.id === this.id) return;
    if (msg.t === 'join') {
      this.handlers.onJoin?.(msg);
      // reply so the newcomer learns about us
      if (this.me) this.send({ t: 'hello', id: this.id, player: this.me });
      return;
    }
    if (msg.t === 'hello') {
      this.handlers.onJoin?.(msg);
      return;
    }
    if (msg.t === 'leave') {
      this.remotes.delete(msg.id);
      this.handlers.onLeave?.(msg);
      return;
    }
    if (msg.t === 'state') {
      const prev = this.remotes.get(msg.id);
      const r = {
        id: msg.id,
        name: msg.name || prev?.name || 'Jugador',
        appearance: msg.appearance || prev?.appearance || {},
        x: prev ? prev.x : msg.x,
        y: prev ? prev.y : msg.y,
        angle: prev ? prev.angle : msg.angle,
        tx: msg.x, ty: msg.y, ta: msg.angle,
        moving: msg.moving || 0,
        vehicle: msg.vehicle || null,
        weapon: msg.weapon || null,
        lastSeen: performance.now(),
      };
      this.remotes.set(msg.id, r);
      this.handlers.onState?.(r);
      return;
    }
    if (msg.t === 'chat') { this.handlers.onChat?.(msg); return; }
    if (msg.t === 'event') { this.handlers.onEvent?.(msg); }
  }

  update(now, me) {
    if (!this.channel || !this.me) return;
    if (now - this.lastSend < 85) return;
    this.lastSend = now;
    this.send({
      t: 'state', id: this.id, name: this.me.name, appearance: this.me.appearance,
      x: Math.round(me.x * 10) / 10, y: Math.round(me.y * 10) / 10, angle: me.angle,
      moving: me.moving, vehicle: me.vehicle, weapon: me.weapon,
    });
    // drop stale remotes
    for (const [id, r] of this.remotes) {
      if (now - r.lastSeen > 6000) { this.remotes.delete(id); this.handlers.onLeave?.({ id, name: r.name }); }
    }
  }

  interpolate(dt) {
    const t = Math.min(1, dt * 11);
    for (const r of this.remotes.values()) {
      r.x += (r.tx - r.x) * t;
      r.y += (r.ty - r.y) * t;
      let d = ((r.ta - r.angle + Math.PI) % (Math.PI * 2)) - Math.PI;
      if (d < -Math.PI) d += Math.PI * 2;
      r.angle += d * t;
    }
  }

  chat(payload) {
    this.send({ t: 'chat', id: this.id, ...payload });
  }

  event(payload) {
    this.send({ t: 'event', id: this.id, ...payload });
  }

  leave() {
    this.send({ t: 'leave', id: this.id, name: this.me?.name });
    try { this.channel?.close(); } catch {}
  }
}

export function randomId() { return Math.random().toString(36).slice(2, 9); }

// HUD, chat, toasts, start screen
import { COLORS } from './data.js';
import { fmtMoney, profile } from './state.js';
import { drawAvatar } from './menus.js';
import { sfx, resumeAudio } from './audio.js';

const $ = (id) => document.getElementById(id);

export const UI = {
  cb: {},
  chatOpen: false,
  creator: { skin: profile.skin, shirt: profile.shirt, pants: profile.pants, accessory: profile.accessory },
  cache: {},
  chatLines: [],

  init(cb) {
    this.cb = cb;
    this.initStart();
    this.bindHUD();
    this.bindChat();
    $('btn-phone').onclick = () => { resumeAudio(); sfx.click(); this.cb.onPhone?.(); };
    $('btn-map').onclick = () => { sfx.click(); this.cb.onMap?.(); };
    $('btn-chat').onclick = () => { this.openChat(); };
    $('btn-sound').onclick = () => { this.cb.onSoundToggle?.(); };
    $('btn-resume').onclick = () => { sfx.click(); this.cb.onResume?.(); };
    $('btn-exit').onclick = () => { sfx.click(); this.cb.onExit?.(); };
    this.buildMobile();
  },

  // ---------- START / CREATOR ----------
  initStart() {
    $('skin-swatches').innerHTML = COLORS.skins.map((c, i) => `<button class="swatch" data-skin="${c}" style="background:${c}" aria-label="Piel ${i + 1}"></button>`).join('');
    $('shirt-swatches').innerHTML = COLORS.shirts.map((c) => `<button class="swatch" data-shirt="${c}" style="background:${c}" aria-label="Camiseta"></button>`).join('');
    $('pants-swatches').innerHTML = COLORS.pants.map((c) => `<button class="swatch" data-pants="${c}" style="background:${c}" aria-label="Pantalón"></button>`).join('');
    const accNames = { none: 'NO', cap: 'GORRA', shades: 'GAFAS', chain: 'CADENA', beanie: 'GORRO' };
    $('acc-swatches').innerHTML = COLORS.accessories.map((a) => `<button class="swatch accessory" data-acc="${a}" aria-label="${a}">${accNames[a]}</button>`).join('');

    document.querySelectorAll('[data-skin]').forEach((b) => b.onclick = () => this.setCreator('skin', b.dataset.skin));
    document.querySelectorAll('[data-shirt]').forEach((b) => b.onclick = () => this.setCreator('shirt', b.dataset.shirt));
    document.querySelectorAll('[data-pants]').forEach((b) => b.onclick = () => this.setCreator('pants', b.dataset.pants));
    document.querySelectorAll('[data-acc]').forEach((b) => b.onclick = () => this.setCreator('accessory', b.dataset.acc));

    $('btn-start').onclick = () => {
      resumeAudio();
      const name = ($('name-input').value || '').trim();
      if (name.length < 2) {
        $('name-input').focus();
        $('name-input').style.borderColor = '#ff4d5e';
        this.toast('Escribe un nombre de rol (mín. 2 letras)', 'bad', 'x');
        setTimeout(() => { $('name-input').style.borderColor = ''; }, 1400);
        return;
      }
      sfx.job();
      this.cb.onStart?.({ name, ...this.creator });
    };
    $('btn-continue').onclick = () => { resumeAudio(); sfx.job(); this.cb.onContinue?.(); };
    $('name-input').addEventListener('keydown', (e) => { if (e.key === 'Enter') $('btn-start').click(); });
    this.refreshCreator();
  },

  setCreator(key, value) {
    this.creator[key] = value;
    this.refreshCreator();
    sfx.click();
  },

  refreshCreator() {
    document.querySelectorAll('[data-skin]').forEach((b) => b.classList.toggle('active', b.dataset.skin === this.creator.skin));
    document.querySelectorAll('[data-shirt]').forEach((b) => b.classList.toggle('active', b.dataset.shirt === this.creator.shirt));
    document.querySelectorAll('[data-pants]').forEach((b) => b.classList.toggle('active', b.dataset.pants === this.creator.pants));
    document.querySelectorAll('[data-acc]').forEach((b) => b.classList.toggle('active', b.dataset.acc === this.creator.accessory));
    const cv = $('avatar-preview');
    if (cv) drawAvatar(cv, this.creator);
  },

  showStart(hasSave) {
    $('start-screen').classList.remove('hidden');
    $('hud').classList.add('hidden');
    $('pause-screen').classList.add('hidden');
    $('mobile-controls').classList.add('hidden');
    $('btn-continue').classList.toggle('hidden', !hasSave);
    $('name-input').value = profile.name || '';
    if (profile.name) {
      this.creator = { skin: profile.skin, shirt: profile.shirt, pants: profile.pants, accessory: profile.accessory };
      this.refreshCreator();
    }
  },

  hideStart() {
    $('start-screen').classList.add('hidden');
    $('hud').classList.remove('hidden');
    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) $('mobile-controls').classList.remove('hidden');
  },

  // ---------- HUD ----------
  bindHUD() {
    $('wanted').innerHTML = Array.from({ length: 5 }, () => '<svg class="icon"><use href="#i-star"/></svg>').join('');
  },

  updateHUD(d) {
    const c = this.cache;
    if (c.money !== d.money) { $('money').textContent = fmtMoney(d.money); c.money = d.money; }
    if (c.bank !== d.bank) { $('bank').textContent = fmtMoney(d.bank); c.bank = d.bank; }
    if (c.health !== d.health) { $('bar-health').style.width = d.health + '%'; $('val-health').textContent = Math.round(d.health); c.health = d.health; }
    if (c.armor !== d.armor) {
      $('bar-armor').style.width = d.armor + '%'; $('val-armor').textContent = Math.round(d.armor);
      $('bar-armor').parentElement.parentElement.classList.toggle('active', d.armor > 0);
      c.armor = d.armor;
    }
    if (c.hunger !== d.hunger) { $('bar-hunger').style.width = d.hunger + '%'; $('val-hunger').textContent = Math.round(d.hunger); c.hunger = d.hunger; }
    if (c.thirst !== d.thirst) { $('bar-thirst').style.width = d.thirst + '%'; $('val-thirst').textContent = Math.round(d.thirst); c.thirst = d.thirst; }
    if (c.clock !== d.clock) { $('clock').textContent = d.clock; $('phone-time').textContent = d.clock; c.clock = d.clock; }
    if (c.location !== d.location) { $('location-name').textContent = d.location; $('zone-label').textContent = d.location.toUpperCase(); c.location = d.location; }
    if (c.online !== d.online) { $('online-count').textContent = d.online + ' en línea'; c.online = d.online; }
    if (c.level !== d.level || c.xp !== d.xp) {
      $('level').textContent = d.level;
      document.querySelector('#xp-bar u').style.width = (d.xp * 100).toFixed(1) + '%';
      c.level = d.level; c.xp = d.xp;
    }
    if (c.wanted !== d.wanted) {
      $('wanted').classList.toggle('hidden', d.wanted <= 0);
      [...$('wanted').children].forEach((el, i) => el.classList.toggle('on', i < d.wanted));
      c.wanted = d.wanted;
    }
    if (c.weapon !== d.weaponKey) {
      if (d.weaponKey) {
        $('weapon-chip').classList.remove('hidden');
        $('weapon-name').textContent = d.weaponName;
        $('weapon-ammo').textContent = d.weaponAmmo;
      } else $('weapon-chip').classList.add('hidden');
      c.weapon = d.weaponKey;
    } else if (d.weaponKey && c.weaponAmmo !== d.weaponAmmo) {
      $('weapon-ammo').textContent = d.weaponAmmo;
      c.weaponAmmo = d.weaponAmmo;
    }
    if (c.vehicle !== d.vehicleKey) {
      if (d.vehicleKey) {
        $('vehicle-chip').classList.remove('hidden');
        $('vehicle-name').textContent = d.vehicleName;
      } else $('vehicle-chip').classList.add('hidden');
      c.vehicle = d.vehicleKey;
    }
    if (d.vehicleKey) {
      $('vehicle-speed').textContent = Math.round(d.speed * 0.42);
      $('vehicle-fuel').textContent = Math.round(d.fuel) + '%';
      $('fuel-fill').style.width = d.fuel + '%';
      $('fuel-fill').style.background = d.fuel < 18 ? '#ff4d5e' : d.fuel < 40 ? '#ffb800' : '#46d98b';
    }
  },

  setPrompt(text) {
    const el = $('interact-prompt');
    if (!text) { el.classList.add('hidden'); return; }
    el.classList.remove('hidden');
    if (this.cache.prompt !== text) { $('interact-text').textContent = text; this.cache.prompt = text; }
  },

  setHint(text) {
    $('action-hint').textContent = text || '';
  },

  setMission(m) {
    const el = $('mission-chip');
    if (!m) { el.classList.add('hidden'); return; }
    el.classList.remove('hidden');
    $('mission-tag').textContent = m.tag || 'TRABAJO';
    $('mission-title').textContent = m.title;
    $('mission-desc').textContent = m.desc;
    $('mission-timer').textContent = m.timer;
    $('mission-distance').textContent = m.distance;
  },

  // ---------- CHAT ----------
  bindChat() {
    const input = $('chat-input');
    input.addEventListener('keydown', (e) => {
      e.stopPropagation();
      if (e.key === 'Enter') {
        const text = input.value.trim();
        input.value = '';
        if (text) this.cb.onChatInput?.(text);
        this.closeChat();
      } else if (e.key === 'Escape') { input.value = ''; this.closeChat(); }
    });
    input.addEventListener('blur', () => { if (this.chatOpen) setTimeout(() => this.closeChat(), 120); });
  },

  openChat() {
    if (this.chatOpen) return;
    this.chatOpen = true;
    $('chat-input-wrap').classList.remove('hidden');
    $('chat-channel').textContent = 'LOCAL';
    setTimeout(() => $('chat-input').focus(), 10);
  },

  closeChat() {
    this.chatOpen = false;
    $('chat-input-wrap').classList.add('hidden');
    $('chat-input').blur();
  },

  chat({ channel = 'local', name = '', text = '', color = '#fff', tag = null }) {
    const log = $('chat-log');
    const line = document.createElement('div');
    line.className = 'chat-line ' + channel;
    const time = new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
    const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
    let tagHtml = '';
    if (tag) tagHtml = `<span class="tag ${tag.cls}">${tag.text}</span>`;
    if (channel === 'system') {
      line.innerHTML = `<span class="ch-time">${time}</span>${esc(text)}`;
    } else if (channel === 'me') {
      line.innerHTML = `<span class="ch-time">${time}</span><b style="color:${color}">${esc(name)}</b> ${esc(text)}`;
    } else if (channel === 'do') {
      line.innerHTML = `<span class="ch-time">${time}</span><span style="color:#8f99a7">* ${esc(text)} *</span>`;
    } else {
      line.innerHTML = `<span class="ch-time">${time}</span>${tagHtml}<b style="color:${color}">${esc(name)}</b>: ${esc(text)}`;
    }
    log.appendChild(line);
    while (log.children.length > 40) log.removeChild(log.firstChild);
    this.chatLines.push(line);
    if (this.chatLines.length > 60) this.chatLines.shift();
    if (!this.chatOpen) sfx.chat();
  },

  // ---------- TOASTS ----------
  toast(text, type = 'info', icon = 'check') {
    const wrap = $('toasts');
    const el = document.createElement('div');
    el.className = 'toast ' + type;
    el.innerHTML = `<svg class="icon"><use href="#i-${icon}"/></svg><span>${text}</span>`;
    wrap.appendChild(el);
    if (wrap.children.length > 4) wrap.removeChild(wrap.firstChild);
    setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 260); }, 3200);
  },

  // ---------- MOBILE ----------
  buildMobile() {
    const actions = document.querySelectorAll('.mob-btn');
    actions.forEach((b) => {
      const act = b.dataset.action;
      b.addEventListener('pointerdown', (e) => {
        e.preventDefault(); e.stopPropagation();
        resumeAudio();
        if (act === 'sprint') this.cb.onMobileSprint?.(true);
        else if (act === 'chat') this.openChat();
        else this.cb.onMobileAction?.(act);
      });
      if (act === 'sprint') b.addEventListener('pointerup', () => this.cb.onMobileSprint?.(false));
      if (act === 'sprint') b.addEventListener('pointerleave', () => this.cb.onMobileSprint?.(false));
    });
  },

  showPause(v) { $('pause-screen').classList.toggle('hidden', !v); },
};

// Character avatar drawing (front view) for creator & shops
function rr(ctx, x, y, w, h, r) {
  const q = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + q, y);
  ctx.arcTo(x + w, y, x + w, y + h, q);
  ctx.arcTo(x + w, y + h, x, y + h, q);
  ctx.arcTo(x, y + h, x, y, q);
  ctx.arcTo(x, y, x + w, y, q);
  ctx.closePath();
}

export function drawAvatar(canvas, app = {}, opts = {}) {
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);
  const skin = app.skin || '#dda57a';
  const shirt = app.shirt || '#ffd400';
  const pants = app.pants || '#252a33';
  const acc = app.accessory || 'none';
  const hair = app.hair || '#241a14';

  ctx.save();
  const s = Math.min(W / 260, H / 300) * (opts.scale || 1);
  ctx.translate(W / 2, H / 2);
  ctx.scale(s, s);
  ctx.translate(0, 8);

  // floor shadow
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath(); ctx.ellipse(0, 128, 62, 12, 0, 0, Math.PI * 2); ctx.fill();

  // legs
  ctx.fillStyle = pants;
  rr(ctx, -40, 30, 34, 88, 10); ctx.fill();
  rr(ctx, 6, 30, 34, 88, 10); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.08)';
  rr(ctx, -37, 34, 8, 76, 4); ctx.fill();
  rr(ctx, 9, 34, 8, 76, 4); ctx.fill();
  // shoes
  ctx.fillStyle = '#15171b';
  rr(ctx, -44, 108, 42, 18, 6); ctx.fill();
  rr(ctx, 2, 108, 42, 18, 6); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.18)';
  ctx.fillRect(-40, 118, 34, 3);
  ctx.fillRect(6, 118, 34, 3);

  // arms
  ctx.fillStyle = skin;
  rr(ctx, -66, -32, 22, 76, 10); ctx.fill();
  rr(ctx, 44, -32, 22, 76, 10); ctx.fill();
  // sleeves
  ctx.fillStyle = shirt;
  rr(ctx, -66, -36, 22, 34, 10); ctx.fill();
  rr(ctx, 44, -36, 22, 34, 10); ctx.fill();
  // hands
  ctx.fillStyle = skin;
  ctx.beginPath(); ctx.arc(-55, 46, 11, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(55, 46, 11, 0, Math.PI * 2); ctx.fill();

  // torso
  ctx.fillStyle = shirt;
  rr(ctx, -48, -42, 96, 86, 20); ctx.fill();
  // torso shading
  ctx.fillStyle = 'rgba(0,0,0,0.16)';
  rr(ctx, 24, -42, 24, 86, 14); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.12)';
  rr(ctx, -40, -36, 16, 70, 8); ctx.fill();
  // collar
  ctx.fillStyle = 'rgba(0,0,0,0.2)';
  ctx.beginPath(); ctx.ellipse(0, -38, 18, 8, 0, 0, Math.PI * 2); ctx.fill();
  // belt
  ctx.fillStyle = '#1b1d22';
  rr(ctx, -48, 34, 96, 12, 3); ctx.fill();
  ctx.fillStyle = '#c9a227';
  ctx.fillRect(-7, 35, 14, 10);
  ctx.fillStyle = '#0f1114';
  ctx.fillRect(-3, 38, 6, 4);

  // neck
  ctx.fillStyle = skin;
  rr(ctx, -12, -58, 24, 22, 8); ctx.fill();
  // head
  ctx.fillStyle = skin;
  ctx.beginPath(); ctx.arc(0, -86, 38, 0, Math.PI * 2); ctx.fill();
  // ears
  ctx.beginPath(); ctx.arc(-38, -86, 8, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(38, -86, 8, 0, Math.PI * 2); ctx.fill();
  // shading
  ctx.fillStyle = 'rgba(0,0,0,0.09)';
  ctx.beginPath(); ctx.arc(12, -80, 30, -0.6, 1.9); ctx.fill();

  // hair
  ctx.fillStyle = hair;
  ctx.beginPath(); ctx.arc(0, -92, 39, Math.PI * 1.02, Math.PI * 1.98); ctx.fill();
  ctx.beginPath(); ctx.arc(-30, -98, 15, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(28, -99, 14, 0, Math.PI * 2); ctx.fill();
  // eyebrows
  ctx.strokeStyle = 'rgba(20,14,10,0.7)'; ctx.lineWidth = 3; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-24, -96); ctx.lineTo(-9, -98); ctx.moveTo(9, -98); ctx.lineTo(24, -96); ctx.stroke();
  // eyes
  ctx.fillStyle = '#15171c';
  ctx.beginPath(); ctx.arc(-16, -88, 4.2, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(16, -88, 4.2, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.8)';
  ctx.beginPath(); ctx.arc(-17.5, -89.5, 1.3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(14.5, -89.5, 1.3, 0, Math.PI * 2); ctx.fill();
  // nose + mouth
  ctx.strokeStyle = 'rgba(120,70,50,0.45)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(0, -86); ctx.lineTo(-2, -78); ctx.lineTo(3, -77); ctx.stroke();
  ctx.strokeStyle = 'rgba(110,50,50,0.6)'; ctx.lineWidth = 2.6;
  ctx.beginPath(); ctx.arc(0, -72, 10, 0.25, Math.PI - 0.25); ctx.stroke();

  // accessories
  if (acc === 'cap') {
    ctx.fillStyle = shirt;
    ctx.beginPath(); ctx.arc(0, -100, 40, Math.PI, Math.PI * 2); ctx.fill();
    rr(ctx, -40, -104, 80, 13, 4); ctx.fill();
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    rr(ctx, -44, -102, 34, 9, 4); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.fillRect(-8, -136, 16, 5);
  } else if (acc === 'beanie') {
    ctx.fillStyle = '#2b3038';
    ctx.beginPath(); ctx.arc(0, -102, 41, Math.PI, Math.PI * 2); ctx.fill();
    rr(ctx, -42, -106, 84, 16, 5); ctx.fill();
    ctx.fillStyle = '#3a4049'; ctx.fillRect(-42, -96, 84, 5);
  } else if (acc === 'shades') {
    ctx.fillStyle = '#0b0d10';
    rr(ctx, -31, -94, 27, 13, 4); ctx.fill();
    rr(ctx, 4, -94, 27, 13, 4); ctx.fill();
    ctx.fillRect(-5, -91, 10, 3);
    ctx.fillStyle = 'rgba(120,180,220,0.35)';
    rr(ctx, -27, -91, 8, 4, 2); ctx.fill();
    rr(ctx, 8, -91, 8, 4, 2); ctx.fill();
  } else if (acc === 'chain') {
    ctx.strokeStyle = '#ffd400'; ctx.lineWidth = 3.5;
    ctx.beginPath(); ctx.arc(0, -54, 22, 0.15, Math.PI - 0.15); ctx.stroke();
    ctx.fillStyle = '#ffd400';
    ctx.beginPath(); ctx.moveTo(0, -26); ctx.lineTo(7, -34); ctx.lineTo(0, -42); ctx.lineTo(-7, -34); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#b88e00'; ctx.beginPath(); ctx.arc(0, -34, 2.5, 0, Math.PI * 2); ctx.fill();
  }

  ctx.restore();
}

export function drawShopArt(canvas, poi, app) {
  if (poi.type === 'clothing') {
    drawAvatar(canvas, app);
    return;
  }
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);
  const color = poi.color || '#ffd400';
  const g = ctx.createRadialGradient(W / 2, H * 0.34, 10, W / 2, H * 0.4, W * 0.75);
  g.addColorStop(0, color + '33');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);

  // shelves / counter background
  ctx.fillStyle = 'rgba(255,255,255,0.045)';
  for (let i = 0; i < 3; i++) {
    const y = 70 + i * 62;
    ctx.fillRect(30, y, W - 60, 7);
    for (let j = 0; j < 5; j++) {
      ctx.fillStyle = `rgba(255,255,255,${0.05 + ((i + j) % 3) * 0.03})`;
      ctx.fillRect(40 + j * 44, y - 30, 28, 28);
    }
  }
  // big badge
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.beginPath(); ctx.arc(W / 2, H * 0.42, 66, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = color; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.arc(W / 2, H * 0.42, 66, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = color;
  ctx.font = '700 64px "Arial Black", Impact, sans-serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(poi.letter || '?', W / 2, H * 0.42 + 4);
  ctx.fillStyle = 'rgba(255,255,255,0.75)';
  ctx.font = '600 12px "Segoe UI", Arial, sans-serif';
  ctx.fillText((poi.name || '').toUpperCase(), W / 2, H * 0.42 + 92);
  ctx.textBaseline = 'alphabetic';
}

