240: function drawTree(ctx, t) {
241:   ctx.fillStyle = 'rgba(0,0,0,0.28)';
242:   ctx.beginPath(); ctx.ellipse(t.x + 4, t.y + 6, t.r * 0.95, t.r * 0.7, 0, 0, Math.PI * 2); ctx.fill();
243:   ctx.fillStyle = `hsl(${t.hue}, 32%, 24%)`;
244:   ctx.beginPath(); ctx.arc(t.x, t.y, t.r, 0, Math.PI * 2); ctx.fill();
245:   ctx.fillStyle = `hsl(${t.hue}, 36%, 31%)`;
246:   ctx.beginPath(); ctx.arc(t.x - t.r * 0.22, t.y - t.r * 0.25, t.r * 0.72, 0, Math.PI * 2); ctx.fill();
247:   ctx.fillStyle = `hsl(${t.hue}, 42%, 38%)`;
248:   ctx.beginPath(); ctx.arc(t.x - t.r * 0.34, t.y - t.r * 0.4, t.r * 0.38, 0, Math.PI * 2); ctx.fill();
249: }
