260: export function renderStatic() {
261:   const c = document.createElement('canvas');
262:   c.width = WORLD.w; c.height = WORLD.h;
263:   const ctx = c.getContext('2d');
264:   drawRoads(ctx);
265: 
266:   const park = city.pois.find((p) => p.type === 'park');
267:   if (park) drawPark(ctx, park);
268:   const gas = city.pois.find((p) => p.type === 'gas');
269:   if (gas) drawGasStation(ctx, gas);
270: 
271:   // building shadows first for depth
272:   for (const b of city.buildings) {
273:     if (b.kind === 'park') continue;
274:     const lift = Math.min(14, b.floors * 2);
275:     ctx.fillStyle = 'rgba(0,0,0,0.22)';
276:     roundRect(ctx, b.x + 10 + lift * 0.35, b.y + 12 + lift * 0.35, b.w, b.h, 4); ctx.fill();
277:   }
278:   for (const b of city.buildings) {
279:     if (b.kind === 'park') continue;
280:     drawBuilding(ctx, b);
281:   }
282: 
283:   // dealer lot markings
284:   const dealer = city.pois.find((p) => p.type === 'dealer');
285:   if (dealer && dealer.carLot) {
286:     const l = dealer.carLot;
287:     ctx.fillStyle = '#2b2f35'; ctx.fillRect(l.x, l.y, l.w, l.h);
288:     ctx.strokeStyle = 'rgba(255,255,255,0.25)'; ctx.lineWidth = 2;
289:     for (let i = 1; i < 4; i++) {
290:       ctx.beginPath(); ctx.moveTo(l.x + i * (l.w / 4), l.y + 8); ctx.lineTo(l.x + i * (l.w / 4), l.y + l.h - 8); ctx.stroke();
291:     }
292:     ctx.fillStyle = 'rgba(255,212,0,0.7)'; ctx.font = `700 12px ${FONT_UI}`; ctx.textAlign = 'center';
293:     ctx.fillText('AUTOS DELUXE', l.x + l.w / 2, l.y + l.h - 10);
294:   }
295: 
296:   for (const t of city.trees) drawTree(ctx, t);
297:   for (const l of city.lamps) drawLamp(ctx, l);
298:   for (const b of city.benches) {
299:     ctx.save(); ctx.translate(b.x, b.y); ctx.rotate(b.a);
300:     ctx.fillStyle = '#5b4a35'; roundRect(ctx, -16, -6, 32, 12, 2); ctx.fill();
301:     ctx.fillStyle = '#6e5a40'; ctx.fillRect(-16, -8, 32, 3);
302:     ctx.restore();
303:   }
304: 
305:   // Block names painted on sidewalks
306:   ctx.textAlign = 'center';
307:   for (let by = 0; by < 5; by++) {
308:     for (let bx = 0; bx < 5; bx++) {
309:       const b = blockBounds(bx, by);
310:       if ((bx + by) % 2 === 0) continue;
311:       ctx.save();
312:       ctx.translate(b.cx, b.y1 + 34);
313:       ctx.fillStyle = 'rgba(255,255,255,0.14)';
314:       ctx.font = `700 11px ${FONT_UI}`;
315:       ctx.fillText('SUNSET CITY', 0, 0);
316:       ctx.restore();
317:     }
318:   }
319: 
320:   // Outer border / ocean hint
321:   const g = ctx.createLinearGradient(0, 0, 0, 70);
322:   g.addColorStop(0, 'rgba(20,50,70,0.9)'); g.addColorStop(1, 'rgba(20,50,70,0)');
323:   ctx.fillStyle = g; ctx.fillRect(0, 0, WORLD.w, 70);
324: 
325:   city.staticCanvas = c;
326:   return c;
327: }
