329: export function buildMinimapBase(size = 760) {
330:   const c = document.createElement('canvas');
331:   c.width = size; c.height = size;
332:   const ctx = c.getContext('2d');
333:   const s = size / WORLD.w;
334:   ctx.fillStyle = '#0d1117'; ctx.fillRect(0, 0, size, size);
335:   if (city.staticCanvas) {
336:     ctx.globalAlpha = 0.72;
337:     ctx.drawImage(city.staticCanvas, 0, 0, size, size);
338:     ctx.globalAlpha = 1;
339:   }
340:   // darken + tint
341:   ctx.fillStyle = 'rgba(8,12,18,0.35)'; ctx.fillRect(0, 0, size, size);
342:   // POI dots
343:   for (const p of city.pois) {
344:     if (!p.door) continue;
345:     const x = p.door.x * s, y = p.door.y * s;
346:     ctx.fillStyle = p.color;
347:     ctx.beginPath(); ctx.arc(x, y, 3.4, 0, Math.PI * 2); ctx.fill();
348:   }
349:   city.minimapCanvas = c;
350:   return c;
351: }
