58: export function addXP(amount) {
59:   profile.xp += amount;
60:   let leveled = false;
61:   while (profile.xp >= xpForLevel(profile.level)) {
62:     profile.xp -= xpForLevel(profile.level);
63:     profile.level += 1;
64:     leveled = true;
65:   }
66:   return leveled;
