30:   if (!enabled) return;
31:   const a = ensure(); if (!a) return;
32:   const o = a.createOscillator();
33:   const g = a.createGain();
34:   o.type = type;
35:   o.frequency.setValueAtTime(freq, a.currentTime);
36:   if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), a.currentTime + dur);
37:   g.gain.setValueAtTime(vol, a.currentTime);
38:   g.gain.exponentialRampToValueAtTime(0.001, a.currentTime + dur);
39:   o.connect(g); g.connect(master);
40:   o.start(); o.stop(a.currentTime + dur + 0.02);
41: }
