45:     ctx.moveTo(x + ROAD_W / 2, 0); ctx.lineTo(x + ROAD_W / 2, WORLD.h); ctx.stroke();
46:   }
47:   for (const y of ROAD_LINES) {
48:     ctx.beginPath(); ctx.moveTo(0, y - ROAD_W / 2); ctx.lineTo(WORLD.w, y - ROAD_W / 2);
49:     ctx.moveTo(0, y + ROAD_W / 2); ctx.lineTo(WORLD.w, y + ROAD_W / 2); ctx.stroke();
50:   }
51: 
52:   // Lane markings
53:   ctx.lineCap = 'butt';
54:   for (const x of ROAD_LINES) {
55:     for (let y = 40; y < WORLD.h; y += 90) {
56:       const near = ROAD_LINES.some((ry) => Math.abs(y - ry) < ROAD_W / 2 + 40);
57:       if (near) continue;
58:       ctx.fillStyle = 'rgba(255,255,255,0.28)';
59:       ctx.fillRect(x - 1.5, y, 3, 44);
60:     }
61:     ctx.fillStyle = 'rgba(255,205,60,0.4)';
62:     ctx.fillRect(x - ROAD_W / 2 + 6, 0, 2, WORLD.h);
63:     ctx.fillRect(x + ROAD_W / 2 - 8, 0, 2, WORLD.h);
64:   }
65:   for (const y of ROAD_LINES) {
66:     for (let x = 40; x < WORLD.w; x += 90) {
67:       const near = ROAD_LINES.some((rx) => Math.abs(x - rx) < ROAD_W / 2 + 40);
68:       if (near) continue;
69:       ctx.fillStyle = 'rgba(255,255,255,0.28)';
70:       ctx.fillRect(x, y - 1.5, 44, 3);
71:     }
72:     ctx.fillStyle = 'rgba(255,205,60,0.4)';
73:     ctx.fillRect(0, y - ROAD_W / 2 + 6, WORLD.w, 2);
74:     ctx.fillRect(0, y + ROAD_W / 2 - 8, WORLD.w, 2);
75:   }
76: 
77:   // Crosswalks
78:   for (const x of ROAD_LINES) {
79:     for (const y of ROAD_LINES) {
80:       for (let i = -2; i <= 2; i++) {
81:         ctx.fillStyle = 'rgba(235,238,242,0.55)';
82:         ctx.fillRect(x + i * 18 - 6, y - ROAD_W / 2 - 26, 12, 22);
83:         ctx.fillRect(x + i * 18 - 6, y + ROAD_W / 2 + 4, 12, 22);
84:         ctx.fillRect(x - ROAD_W / 2 - 26, y + i * 18 - 6, 22, 12);
85:         ctx.fillRect(x + ROAD_W / 2 + 4, y + i * 18 - 6, 22, 12);
86:       }
87:     }
88:   }
89: 
90:   // Block pads (sidewalk + interior)
91:   for (let by = 0; by < 5; by++) {
92:     for (let bx = 0; bx < 5; bx++) {
93:       const b = blockBounds(bx, by);
94:       ctx.fillStyle = '#3a3e45';
95:       roundRect(ctx, b.x0 - 12, b.y0 - 12, b.w + 24, b.h + 24, 8);
96:       ctx.fill();
97:       ctx.fillStyle = '#2c3037';
98:       roundRect(ctx, b.x0, b.y0, b.w, b.h, 4);
99:       ctx.fill();
100:       // sidewalk seams
101:       ctx.strokeStyle = 'rgba(0,0,0,0.16)';
102:       ctx.lineWidth = 1;
103:       for (let x = b.x0 - 12; x < b.x1 + 12; x += 30) {
104:         ctx.beginPath(); ctx.moveTo(x, b.y0 - 12); ctx.lineTo(x, b.y0); ctx.stroke();
105:         ctx.beginPath(); ctx.moveTo(x, b.y1); ctx.lineTo(x, b.y1 + 12); ctx.stroke();
106:       }
107:       for (let y = b.y0 - 12; y < b.y1 + 12; y += 30) {
108:         ctx.beginPath(); ctx.moveTo(b.x0 - 12, y); ctx.lineTo(b.x0, y); ctx.stroke();
109:         ctx.beginPath(); ctx.moveTo(b.x1, y); ctx.lineTo(b.x1 + 12, y); ctx.stroke();
110:       }
111:     }
112:   }
113: }
