8:     this.channel = null;
9:     try {
10:       this.channel = new BroadcastChannel('sunset-city-rp');
11:       this.channel.onmessage = (e) => this.onMessage(e.data);
12:     } catch { this.channel = null; }
13:     this.online = !!this.channel;
14:   }
15: 
16:   on(handlers) { this.handlers = { ...this.handlers, ...handlers }; }
