23:   send(msg) {
24:     if (!this.channel) return;
25:     try { this.channel.postMessage(msg); } catch {}
26:   }
27: 
28:   onMessage(msg) {
29:     if (!msg || msg.id === this.id) return;
30:     if (msg.t === 'join') {
31:       this.handlers.onJoin?.(msg);
32:       // reply so the newcomer learns about us
33:       if (this.me) this.send({ t: 'hello', id: this.id, player: this.me });
34:       return;
35:     }
36:     if (msg.t === 'hello') {
37:       this.handlers.onJoin?.(msg);
38:       return;
39:     }
40:     if (msg.t === 'leave') {
41:       this.remotes.delete(msg.id);
42:       this.handlers.onLeave?.(msg);
43:       return;
44:     }
45:     if (msg.t === 'state') {
46:       const prev = this.remotes.get(msg.id);
47:       const r = {
48:         id: msg.id,
49:         name: msg.name || prev?.name || 'Jugador',
50:         appearance: msg.appearance || prev?.appearance || {},
51:         x: prev ? prev.x : msg.x,
52:         y: prev ? prev.y : msg.y,
53:         angle: prev ? prev.angle : msg.angle,
54:         tx: msg.x, ty: msg.y, ta: msg.angle,
55:         moving: msg.moving || 0,
56:         vehicle: msg.vehicle || null,
57:         weapon: msg.weapon || null,
58:         lastSeen: performance.now(),
59:       };
60:       this.remotes.set(msg.id, r);
61:       this.handlers.onState?.(r);
62:       return;
63:     }
64:     if (msg.t === 'chat') { this.handlers.onChat?.(msg); return; }
65:     if (msg.t === 'event') { this.handlers.onEvent?.(msg); }
66:   }
