71:     this.lastSend = now;
72:     this.send({
73:       t: 'state', id: this.id, name: this.me.name, appearance: this.me.appearance,
74:       x: Math.round(me.x * 10) / 10, y: Math.round(me.y * 10) / 10, angle: me.angle,
75:       moving: me.moving, vehicle: me.vehicle, weapon: me.weapon,
76:     });
