355: export function drawPerson(ctx, p, opts = {}) {
356:   const r = opts.radius || 11;
357:   const skin = p.skin || '#dda57a';
358:   const shirt = p.shirt || '#ffd400';
359:   const pants = p.pants || '#252a33';
360:   const acc = p.accessory || 'none';
361:   const moving = (p.moving || 0);
362:   const t = p.walkPhase || 0;
363:   const swing = Math.sin(t) * (moving > 0.1 ? 4 : 0);
364: 
365:   ctx.save();
366:   ctx.translate(p.x, p.y);
367:   // shadow
368:   ctx.fillStyle = 'rgba(0,0,0,0.32)';
369:   ctx.beginPath(); ctx.ellipse(2, 3, r * 1.05, r * 0.78, 0, 0, Math.PI * 2); ctx.fill();
370:   ctx.rotate((p.angle || 0) + Math.PI / 2);
371: 
372:   // legs
373:   ctx.fillStyle = pants;
374:   roundRect(ctx, -r * 0.62, r * 0.05 + swing, r * 0.45, r * 0.9, 2.5); ctx.fill();
375:   roundRect(ctx, r * 0.17, r * 0.05 - swing, r * 0.45, r * 0.9, 2.5); ctx.fill();
376:   // shoes
377:   ctx.fillStyle = '#14161a';
378:   ctx.fillRect(-r * 0.62, r * 0.78 + swing, r * 0.45, r * 0.2);
379:   ctx.fillRect(r * 0.17, r * 0.78 - swing, r * 0.45, r * 0.2);
380: 
381:   // torso
382:   ctx.fillStyle = shirt;
383:   roundRect(ctx, -r * 0.72, -r * 0.55, r * 1.44, r * 1.05, r * 0.38); ctx.fill();
384:   ctx.strokeStyle = 'rgba(0,0,0,0.25)'; ctx.lineWidth = 1;
385:   roundRect(ctx, -r * 0.72, -r * 0.55, r * 1.44, r * 1.05, r * 0.38); ctx.stroke();
386:   // arms
387:   ctx.fillStyle = skin;
388:   ctx.beginPath(); ctx.arc(-r * 0.78, -r * 0.05 + swing * 0.5, r * 0.26, 0, Math.PI * 2); ctx.fill();
389:   ctx.beginPath(); ctx.arc(r * 0.78, -r * 0.05 - swing * 0.5, r * 0.26, 0, Math.PI * 2); ctx.fill();
390: 
391:   // head
392:   const hx = 0, hy = -r * 0.42;
393:   ctx.fillStyle = skin;
394:   ctx.beginPath(); ctx.arc(hx, hy, r * 0.62, 0, Math.PI * 2); ctx.fill();
395:   // hair
396:   ctx.fillStyle = p.hair || '#241a14';
397:   ctx.beginPath(); ctx.arc(hx, hy - r * 0.16, r * 0.6, Math.PI * 1.03, Math.PI * 1.97); ctx.fill();
398: 
399:   if (acc === 'cap') {
400:     ctx.fillStyle = p.capColor || shirt;
401:     ctx.beginPath(); ctx.arc(hx, hy, r * 0.64, Math.PI, Math.PI * 2); ctx.fill();
402:     ctx.fillRect(hx - r * 0.64, hy - r * 0.12, r * 1.28, r * 0.22);
403:   } else if (acc === 'beanie') {
404:     ctx.fillStyle = '#2a2e36';
405:     ctx.beginPath(); ctx.arc(hx, hy - r * 0.08, r * 0.62, Math.PI * 0.98, Math.PI * 2.02); ctx.fill();
406:     ctx.fillStyle = '#3a404b'; ctx.fillRect(hx - r * 0.62, hy - r * 0.2, r * 1.24, r * 0.2);
407:   } else if (acc === 'shades') {
408:     ctx.fillStyle = '#0b0d10';
409:     ctx.fillRect(hx - r * 0.5, hy - r * 0.02, r, r * 0.2);
410:   } else if (acc === 'chain') {
411:     ctx.fillStyle = '#ffd400';
412:     ctx.beginPath(); ctx.arc(hx, hy + r * 0.52, r * 0.16, 0, Math.PI * 2); ctx.fill();
413:   }
414: 
415:   // weapon in hand
416:   if (p.weapon && opts.showWeapon) {
417:     ctx.fillStyle = '#20242b';
418:     ctx.fillRect(r * 0.7, -r * 0.15, r * 1.15, r * 0.18);
419:     ctx.fillStyle = '#3a404a';
420:     ctx.fillRect(r * 0.72, -r * 0.22, r * 0.5, r * 0.3);
421:   }
422: 
423:   ctx.restore();
424: 
425:   // name tag
426:   if (opts.nameTag) {
427:     const label = p.name || 'Jugador';
428:     ctx.save();
429:     ctx.font = `700 11px ${FONT_UI}`;
430:     ctx.textAlign = 'center';
431:     const w = ctx.measureText(label).width + 14;
432:     ctx.fillStyle = 'rgba(6,8,11,0.66)';
433:     roundRect(ctx, p.x - w / 2, p.y - r - 26, w, 17, 4); ctx.fill();
434:     ctx.fillStyle = opts.tagColor || '#fff';
435:     ctx.fillText(label, p.x, p.y - r - 13);
436:     ctx.restore();
437:   }
438: }
