519: export function drawMarker(ctx, x, y, color, letter, time) {
520:   const bob = Math.sin(time * 3) * 3;
521:   ctx.save();
522:   ctx.translate(x, y + bob);
523:   ctx.fillStyle = 'rgba(0,0,0,0.3)';
524:   ctx.beginPath(); ctx.ellipse(0, 18 - bob, 16, 6, 0, 0, Math.PI * 2); ctx.fill();
525:   ctx.fillStyle = color;
526:   ctx.beginPath();
527:   ctx.moveTo(0, 0); ctx.lineTo(11, 9); ctx.lineTo(0, 26); ctx.lineTo(-11, 9); ctx.closePath();
528:   ctx.fill();
529:   ctx.strokeStyle = 'rgba(255,255,255,0.75)'; ctx.lineWidth = 2; ctx.stroke();
530:   ctx.fillStyle = '#111';
531:   ctx.font = `700 12px ${FONT}`; ctx.textAlign = 'center';
532:   ctx.fillText(letter, 0, 13);
533:   ctx.restore();
534: }
