542:   ctx.fillStyle = 'rgba(255,212,0,0.16)';
543:   ctx.beginPath(); ctx.ellipse(0, 0, 26 * pulse, 14 * pulse, 0, 0, Math.PI * 2); ctx.fill();
544:   ctx.fillStyle = 'rgba(255,212,0,0.9)';
