124:   ctx.beginPath();
125:   ctx.moveTo(r.x + 20, r.y + r.h * 0.5); ctx.lineTo(r.x + r.w - 20, r.y + r.h * 0.5);
126:   ctx.moveTo(r.x + r.w * 0.5, r.y + 20); ctx.lineTo(r.x + r.w * 0.5, r.y + r.h - 20);
127:   ctx.stroke();
128:   ctx.strokeStyle = '#a39884'; ctx.lineWidth = 16; ctx.stroke();
129:   // fountain
130:   const cx = poi.cx, cy = poi.cy;
131:   ctx.fillStyle = 'rgba(0,0,0,0.28)'; ctx.beginPath(); ctx.ellipse(cx + 4, cy + 6, 62, 62, 0, 0, Math.PI * 2); ctx.fill();
132:   ctx.fillStyle = '#8f8b80'; ctx.beginPath(); ctx.arc(cx, cy, 58, 0, Math.PI * 2); ctx.fill();
133:   ctx.fillStyle = '#3d7e9e'; ctx.beginPath(); ctx.arc(cx, cy, 47, 0, Math.PI * 2); ctx.fill();
134:   ctx.fillStyle = '#5ba7c7'; ctx.beginPath(); ctx.arc(cx, cy, 40, 0, Math.PI * 2); ctx.fill();
135:   ctx.fillStyle = '#a8a294'; ctx.beginPath(); ctx.arc(cx, cy, 12, 0, Math.PI * 2); ctx.fill();
136:   ctx.strokeStyle = 'rgba(220,245,255,0.5)'; ctx.lineWidth = 2;
137:   for (let i = 0; i < 3; i++) { ctx.beginPath(); ctx.arc(cx, cy, 20 + i * 8, 0, Math.PI * 2); ctx.stroke(); }
138:   // sign
139:   ctx.fillStyle = '#1e3326';
140:   roundRect(ctx, cx - 74, r.y + r.h - 46, 148, 26, 5); ctx.fill();
141:   ctx.fillStyle = '#cfe6d8'; ctx.font = `700 12px ${FONT_UI}`; ctx.textAlign = 'center';
142:   ctx.fillText('PARQUE CENTRAL', cx, r.y + r.h - 28);
