161: function drawBuilding(ctx, b) {
162:   const lift = Math.min(14, b.floors * 2);
163:   // shadow
164:   ctx.fillStyle = 'rgba(0,0,0,0.38)';
165:   roundRect(ctx, b.x + 7 + lift * 0.4, b.y + 9 + lift * 0.4, b.w, b.h, 4); ctx.fill();
166: 
167:   // wall sides
168:   ctx.fillStyle = shade(b.wall, -22);
169:   roundRect(ctx, b.x, b.y, b.w, b.h, 4); ctx.fill();
170:   ctx.fillStyle = b.roof;
171:   roundRect(ctx, b.x + 3, b.y + 3, b.w - 6, b.h - 6, 3); ctx.fill();
172: 
173:   // roof inset / edge
174:   ctx.strokeStyle = 'rgba(255,255,255,0.09)'; ctx.lineWidth = 2;
175:   roundRect(ctx, b.x + 9, b.y + 9, b.w - 18, b.h - 18, 2); ctx.stroke();
176:   ctx.fillStyle = 'rgba(0,0,0,0.13)';
177:   ctx.fillRect(b.x + 9, b.y + 9, b.w - 18, b.h - 18);
178: 
179:   // rooftop details
180:   const seed = (b.x * 13 + b.y * 7) % 97;
181:   const n = 1 + (seed % 3);
182:   for (let i = 0; i < n; i++) {
183:     const w = 18 + ((seed * (i + 2)) % 26);
184:     const h = 14 + ((seed * (i + 3)) % 20);
185:     const x = b.x + 22 + ((seed * (i + 5) * 7) % Math.max(1, b.w - 60));
186:     const y = b.y + 22 + ((seed * (i + 9) * 5) % Math.max(1, b.h - 60));
187:     ctx.fillStyle = shade(b.trim, -12);
188:     roundRect(ctx, x, y, w, h, 2); ctx.fill();
189:     ctx.fillStyle = 'rgba(255,255,255,0.07)'; ctx.fillRect(x + 2, y + 2, w - 4, 3);
190:   }
191:   // skylight strip
192:   ctx.fillStyle = 'rgba(120,160,190,0.16)';
193:   ctx.fillRect(b.x + b.w * 0.62, b.y + 18, b.w * 0.24, 10);
194: 
195:   // storefront / awning on south face
196:   if (b.kind !== 'generic') {
197:     const poi = city.pois.find((p) => p.id === b.poiId);
198:     const color = poi?.color || '#ffd400';
199:     const aw = Math.min(b.w - 24, 230);
200:     const ax = b.x + (b.w - aw) / 2;
201:     const ay = b.y + b.h - 30;
202:     ctx.fillStyle = shade(color, -35);
203:     roundRect(ctx, ax, ay, aw, 26, 4); ctx.fill();
204:     ctx.fillStyle = color;
205:     for (let i = 0; i < aw; i += 18) ctx.fillRect(ax + i, ay, Math.min(9, aw - i), 12);
206:     ctx.fillStyle = 'rgba(0,0,0,0.35)'; ctx.fillRect(ax, ay + 12, aw, 3);
207:     // sign text
208:     ctx.fillStyle = '#fff';
209:     ctx.font = `700 ${Math.min(13, aw / 12)}px ${FONT_UI}`;
210:     ctx.textAlign = 'center';
211:     ctx.shadowColor = 'rgba(0,0,0,0.7)'; ctx.shadowBlur = 4;
212:     ctx.fillText(poi?.name?.toUpperCase() || b.name.toUpperCase(), b.x + b.w / 2, ay + 22);
213:     ctx.shadowBlur = 0;
214:     // door
215:     const dx = b.door.x, dy = b.door.y;
216:     ctx.fillStyle = '#101318';
217:     roundRect(ctx, dx - 20, dy - 8, 40, 16, 3); ctx.fill();
218:     ctx.fillStyle = color;
219:     ctx.globalAlpha = 0.75; ctx.fillRect(dx - 14, dy - 4, 28, 3); ctx.globalAlpha = 1;
220:     // icon badge above door
221:     ctx.fillStyle = 'rgba(0,0,0,0.55)';
222:     ctx.beginPath(); ctx.arc(dx, dy + 20, 13, 0, Math.PI * 2); ctx.fill();
223:     ctx.fillStyle = color;
224:     ctx.beginPath(); ctx.arc(dx, dy + 20, 11, 0, Math.PI * 2); ctx.fill();
225:     ctx.fillStyle = '#111';
226:     ctx.font = `700 12px ${FONT}`; ctx.textAlign = 'center';
227:     ctx.fillText(poi?.letter || '?', dx, dy + 24);
228:   } else {
229:     // generic sign
230:     ctx.fillStyle = 'rgba(255,255,255,0.5)';
231:     ctx.font = `600 10px ${FONT_UI}`; ctx.textAlign = 'center';
232:     ctx.fillText(b.name, b.x + b.w / 2, b.y + b.h - 14);
233:     // entrance
234:     const dx = b.door.x, dy = b.door.y;
235:     ctx.fillStyle = '#15181d'; ctx.fillRect(dx - 13, dy - 6, 26, 12);
236:     ctx.fillStyle = 'rgba(255,210,90,0.5)'; ctx.fillRect(dx - 9, dy - 3, 18, 2);
237:   }
238: }
