246:   ctx.beginPath(); ctx.arc(t.x - t.r * 0.22, t.y - t.r * 0.25, t.r * 0.72, 0, Math.PI * 2); ctx.fill();
247:   ctx.fillStyle = `hsl(${t.hue}, 42%, 38%)`;
248:   ctx.beginPath(); ctx.arc(t.x - t.r * 0.34, t.y - t.r * 0.4, t.r * 0.38, 0, Math.PI * 2); ctx.fill();
