429:     ctx.font = `700 11px ${FONT_UI}`;
430:     ctx.textAlign = 'center';
431:     const w = ctx.measureText(label).width + 14;
432:     ctx.fillStyle = 'rgba(6,8,11,0.66)';
433:     roundRect(ctx, p.x - w / 2, p.y - r - 26, w, 17, 4); ctx.fill();
