43: function noise(dur, vol = 0.4, filterFreq = 900) {
44:   if (!enabled) return;
45:   const a = ensure(); if (!a) return;
46:   const len = Math.floor(a.sampleRate * dur);
47:   const buf = a.createBuffer(1, len, a.sampleRate);
48:   const d = buf.getChannelData(0);
49:   for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
50:   const src = a.createBufferSource(); src.buffer = buf;
51:   const f = a.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = filterFreq;
52:   const g = a.createGain(); g.gain.value = vol;
53:   src.connect(f); f.connect(g); g.connect(master);
54:   src.start();
55: }
