175:       const x = rand(r.x + 24, r.x + r.w - 24);
176:       const y = rand(r.y + 24, r.y + r.h - 24);
177:       if (dist(x, y, park.cx, park.cy) < 72) continue;
178:       city.trees.push({ x, y, r: rand(16, 25), hue: rand(95, 145) });
179:     }
180:     for (let i = 0; i < 5; i++) {
181:       const a = (i / 5) * Math.PI * 2;
182:       city.benches.push({ x: park.cx + Math.cos(a) * 92, y: park.cy + Math.sin(a) * 92, a });
183:     }
184:   }
185:   for (let i = 0; i < 30; i++) {
186:     const line = pick(ROAD_LINES);
187:     const along = rand(240, WORLD.w - 240);
188:     city.trees.push({ x: line + ROAD_W / 2 + rand(8, 16), y: along, r: rand(9, 14), hue: rand(100, 140), small: true });
189:   }
