191:   // Crosswalks at intersections
192:   for (const x of ROAD_LINES) {
193:     for (const y of ROAD_LINES) {
194:       city.crosswalks.push({ x, y });
195:     }
196:   }
197: 
198:   // Parked cars along curbs
199:   const carColors = ['#c0392b', '#2c3e50', '#ecf0f1', '#f39c12', '#27ae60', '#8e44ad', '#2980b9', '#7f8c8d', '#d35400', '#16a085'];
200:   let carIdx = 0;
201:   for (const line of ROAD_LINES.slice(1, 5)) {
202:     for (let t = 480; t < WORLD.w - 300; t += 300) {
203:       if (rr() < 0.55) {
204:         const type = pick(['sedan', 'compact', 'suv', 'sports', 'van', 'taxi']);
205:         city.parked.push({
206:           x: t + rand(-40, 40), y: line - ROAD_W / 2 + 34, angle: 0,
207:           type, color: carColors[carIdx++ % carColors.length], parked: true,
208:         });
209:       }
210:       if (rr() < 0.45) {
211:         const type = pick(['sedan', 'compact', 'suv', 'sports', 'van']);
212:         city.parked.push({
213:           x: line + ROAD_W / 2 - 34, y: t + rand(-40, 40), angle: Math.PI / 2,
214:           type, color: carColors[carIdx++ % carColors.length], parked: true,
215:         });
