154:     ctx.fillStyle = '#d8dbe0'; roundRect(ctx, p.x - 14, p.y - 22, 28, 38, 4); ctx.fill();
155:     ctx.fillStyle = '#b5352f'; ctx.fillRect(p.x - 14, p.y - 22, 28, 10);
156:     ctx.fillStyle = '#1b1e23'; ctx.fillRect(p.x - 8, p.y - 8, 16, 12);
157:     ctx.fillStyle = '#46d98b'; ctx.fillRect(p.x - 6, p.y - 6, 12, 3);
158:   }
