251: function drawLamp(ctx, l) {
252:   ctx.fillStyle = 'rgba(0,0,0,0.3)';
253:   ctx.beginPath(); ctx.ellipse(l.x + 2, l.y + 3, 5, 3, 0, 0, Math.PI * 2); ctx.fill();
254:   ctx.fillStyle = '#4a4f57';
255:   ctx.beginPath(); ctx.arc(l.x, l.y, 3.4, 0, Math.PI * 2); ctx.fill();
256:   ctx.fillStyle = 'rgba(255,220,130,0.35)';
257:   ctx.beginPath(); ctx.arc(l.x, l.y, 7, 0, Math.PI * 2); ctx.fill();
