440: export function drawVehicle(ctx, v, opts = {}) {
441:   const def = VEHICLE_TYPES[v.type] || VEHICLE_TYPES.sedan;
442:   const L = def.len, W = def.wid;
443:   ctx.save();
444:   ctx.translate(v.x, v.y);
445:   ctx.fillStyle = 'rgba(0,0,0,0.35)';
446:   roundRect(ctx, -L / 2 + 4, -W / 2 + 5, L, W, 10); ctx.fill();
447:   ctx.rotate(v.angle || 0);
448: 
449:   // wheels
450:   ctx.fillStyle = '#0d0f12';
451:   roundRect(ctx, -L * 0.34, -W / 2 - 2, L * 0.2, 5, 2); ctx.fill();
452:   roundRect(ctx, L * 0.16, -W / 2 - 2, L * 0.2, 5, 2); ctx.fill();
453:   roundRect(ctx, -L * 0.34, W / 2 - 3, L * 0.2, 5, 2); ctx.fill();
454:   roundRect(ctx, L * 0.16, W / 2 - 3, L * 0.2, 5, 2); ctx.fill();
455: 
456:   // body
457:   const color = v.color || '#c0392b';
458:   ctx.fillStyle = color;
459:   roundRect(ctx, -L / 2, -W / 2, L, W, 9); ctx.fill();
460:   // body shade
461:   ctx.fillStyle = 'rgba(0,0,0,0.18)';
462:   roundRect(ctx, -L / 2 + 3, W / 2 - 8, L - 6, 5, 3); ctx.fill();
463:   // hood/trunk lines
464:   ctx.strokeStyle = 'rgba(0,0,0,0.28)'; ctx.lineWidth = 1.5;
465:   ctx.beginPath(); ctx.moveTo(-L * 0.2, -W / 2 + 3); ctx.lineTo(-L * 0.2, W / 2 - 3);
466:   ctx.moveTo(L * 0.22, -W / 2 + 3); ctx.lineTo(L * 0.22, W / 2 - 3); ctx.stroke();
467: 
468:   // cabin
469:   ctx.fillStyle = 'rgba(15,20,26,0.9)';
470:   roundRect(ctx, -L * 0.17, -W / 2 + 5, L * 0.38, W - 10, 5); ctx.fill();
471:   ctx.fillStyle = 'rgba(120,170,200,0.4)';
472:   roundRect(ctx, -L * 0.13, -W / 2 + 7, L * 0.13, W - 14, 3); ctx.fill();
473:   roundRect(ctx, L * 0.04, -W / 2 + 7, L * 0.1, W - 14, 3); ctx.fill();
474:   // roof stripe
475:   ctx.fillStyle = 'rgba(255,255,255,0.09)';
476:   ctx.fillRect(-L * 0.05, -W / 2 + 6, L * 0.16, W - 12);
477: 
478:   // lights
479:   ctx.fillStyle = '#fff4c4';
480:   roundRect(ctx, L / 2 - 5, -W / 2 + 5, 4, 8, 2); ctx.fill();
481:   roundRect(ctx, L / 2 - 5, W / 2 - 13, 4, 8, 2); ctx.fill();
482:   ctx.fillStyle = '#ff3b30';
483:   roundRect(ctx, -L / 2 + 1, -W / 2 + 5, 3, 7, 1); ctx.fill();
484:   roundRect(ctx, -L / 2 + 1, W / 2 - 12, 3, 7, 1); ctx.fill();
485: 
486:   if (v.type === 'taxi') {
487:     ctx.fillStyle = '#ffd400';
488:     roundRect(ctx, -L * 0.08, -W / 2 + 8, L * 0.16, W - 16, 2); ctx.fill();
489:     ctx.fillStyle = '#111';
490:     ctx.font = `700 8px ${FONT_UI}`; ctx.textAlign = 'center';
491:     ctx.fillText('TAXI', 0, 3);
492:   }
493:   if (v.type === 'van') {
494:     ctx.fillStyle = 'rgba(255,255,255,0.13)';
495:     roundRect(ctx, -L * 0.42, -W / 2 + 6, L * 0.18, W - 12, 3); ctx.fill();
496:   }
497: 
498:   // damage
499:   if (v.damage > 40) {
500:     ctx.strokeStyle = 'rgba(20,20,20,0.6)'; ctx.lineWidth = 2;
501:     ctx.beginPath(); ctx.moveTo(-L * 0.3, -W * 0.2); ctx.lineTo(-L * 0.1, W * 0.1); ctx.lineTo(-L * 0.22, W * 0.3); ctx.stroke();
502:   }
503:   ctx.restore();
504: 
505:   // night headlights
506:   if (opts.night) {
507:     ctx.save();
508:     ctx.translate(v.x, v.y); ctx.rotate(v.angle);
509:     const grad = ctx.createRadialGradient(L / 2, 0, 4, L / 2, 0, 190);
510:     grad.addColorStop(0, 'rgba(255,244,190,0.28)');
511:     grad.addColorStop(0.5, 'rgba(255,244,190,0.09)');
512:     grad.addColorStop(1, 'rgba(255,244,190,0)');
513:     ctx.fillStyle = grad;
514:     ctx.beginPath(); ctx.moveTo(L / 2, 0); ctx.arc(L / 2, 0, 190, -0.4, 0.4); ctx.closePath(); ctx.fill();
515:     ctx.restore();
516:   }
