147: export function drawShopArt(canvas, poi, app) {
148:   if (poi.type === 'clothing') {
149:     drawAvatar(canvas, app);
150:     return;
151:   }
152:   const ctx = canvas.getContext('2d');
153:   const W = canvas.width, H = canvas.height;
154:   ctx.clearRect(0, 0, W, H);
155:   const color = poi.color || '#ffd400';
156:   const g = ctx.createRadialGradient(W / 2, H * 0.34, 10, W / 2, H * 0.4, W * 0.75);
157:   g.addColorStop(0, color + '33');
158:   g.addColorStop(1, 'rgba(0,0,0,0)');
159:   ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
160: 
161:   // shelves / counter background
162:   ctx.fillStyle = 'rgba(255,255,255,0.045)';
163:   for (let i = 0; i < 3; i++) {
164:     const y = 70 + i * 62;
165:     ctx.fillRect(30, y, W - 60, 7);
166:     for (let j = 0; j < 5; j++) {
167:       ctx.fillStyle = `rgba(255,255,255,${0.05 + ((i + j) % 3) * 0.03})`;
168:       ctx.fillRect(40 + j * 44, y - 30, 28, 28);
169:     }
170:   }
171:   // big badge
172:   ctx.fillStyle = 'rgba(0,0,0,0.55)';
173:   ctx.beginPath(); ctx.arc(W / 2, H * 0.42, 66, 0, Math.PI * 2); ctx.fill();
174:   ctx.strokeStyle = color; ctx.lineWidth = 3;
175:   ctx.beginPath(); ctx.arc(W / 2, H * 0.42, 66, 0, Math.PI * 2); ctx.stroke();
176:   ctx.fillStyle = color;
177:   ctx.font = '700 64px "Arial Black", Impact, sans-serif';
178:   ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
179:   ctx.fillText(poi.letter || '?', W / 2, H * 0.42 + 4);
180:   ctx.fillStyle = 'rgba(255,255,255,0.75)';
181:   ctx.font = '600 12px "Segoe UI", Arial, sans-serif';
182:   ctx.fillText((poi.name || '').toUpperCase(), W / 2, H * 0.42 + 92);
183:   ctx.textBaseline = 'alphabetic';
184: }
